   "scenario":"Две недели назад опубликована страница услуги /uslugi/tehnicheskiy-audit. Она открывается в браузере, есть в меню сайта и добавлена в sitemap.xml. В поиске по точной фразе из текста страницы её нет. В отчёте об индексировании Search Console она в группе «Просканирована — не проиндексирована».",
   "solution":"Обход состоялся, значит доступность и robots.txt проблемой не являются. Дальше проверяются директивы индексации и канонизация. Статус «Просканирована — не проиндексирована» чаще всего означает, что Google счёл содержимое недостаточно самостоятельным: страница дублирует существующую услугу или почти не отличается от неё по смыслу. Практический ход: открыть проверку URL, посмотреть выбранный Google канонический адрес; если он указывает на другую страницу — это подтверждение версии о дублировании. Решение — различить содержимое по существу, а не косметически, усилить внутренние ссылки на страницу с осмысленным анкором, и только после этого отправить на переобход. Если содержимое действительно дублирует другую страницу, честный вывод — объединить их, а не пытаться проиндексировать обе.",
