   "scenario":"Три недели назад выкатили редизайн сайта. Через неделю после релиза органический трафик начал снижаться и упал примерно на 40%. Заказчик считает, что виновато обновление алгоритма Google, о котором прочитал в новостях. Дизайн действительно стал лучше, отказы визуально не выросли.",
   "solution":"Порядок такой: сначала подтвердить факт и определить точную дату по Search Console, затем сопоставить её с датой релиза. Разрыв в 5-7 дней типичен: поисковику нужно время, чтобы обойти изменённые страницы. Дальше идёт список собственных изменений. Наиболее частые находки при редизайне: перенесённый с тестового сервера robots.txt с полным запретом, отсутствующие 301 со старых URL на новые, потерянные при переносе шаблона метаданные, вырезанные блоки контента, изменившаяся навигация с потерей внутренних ссылок. Практический приём приоритизации: соединить выгрузку краулера с данными Search Console по URL и чинить в первую очередь страницы, которые до релиза давали клики. Внешние причины проверяются последними: сезонность — сравнением с аналогичным периодом прошлого года, обновления алгоритмов — по датам официальных анонсов. Заказчику ответ формулируется без обвинений: «проверил и релиз, и внешние причины; данные указывают на то-то».",
