   "solution":"Сначала подтверждение: фильтр по запросу в отчёте эффективности показывает оба URL и их чередование. Дальше ключевой вопрос — про разное они или про одно. Если выдача по запросу состоит из коммерческих страниц, интент коммерческий, и статья просто перехватывает часть показов: её нужно переориентировать на явно информационные запросы («что входит в технический аудит», «как проводится аудит»), убрав из неё коммерческие формулировки и цены, и поставить с неё ссылку на услугу. Если выдача информационная, наоборот — основной становится статья, а услуга ссылается на неё. Canonical в обоих вариантах не подходит: страницы содержательно разные, и такое указание будет проигнорировано либо уберёт из выдачи нужную страницу. Обязательный шаг после решения — перестроить внутренние ссылки: анкор «технический аудит сайта» должен вести на выбранную основную страницу, а не на обе.",
