   "scenario":"В интернет-магазине фильтры каталога формируют адреса вида /catalog?color=red&size=42&sort=price&page=3. В индексе более 80 000 таких страниц, при том что товаров около 4 000. Новые карточки товара появляются в поиске через две-три недели. В отчёте индексирования растёт группа «Обнаружена — не проиндексирована».",
   "solution":"Симптом здесь ясен: 80 000 адресов при 4 000 товаров означают, что обход тратится на комбинации фильтров, а не на карточки — отсюда и задержка появления новых товаров, и рост группы «Обнаружена — не проиндексирована». Решение начинается с классификации, потому что для каждого типа параметров оно своё. Сортировка и метки отслеживания не создают самостоятельной ценности: им ставят canonical на базовую страницу. Фасетные фильтры делят по спросу: комбинации, под которые есть реальные запросы и подготовленное содержимое (обычно один-два признака), оставляют открытыми как посадочные страницы; остальные закрывают noindex и ограничивают их обход. Пагинация остаётся с самоссылающимся canonical — иначе часть каталога исчезнет из обхода. Закрывать всё одним правилом в robots.txt нельзя по двум причинам: правило закроет и нужные страницы фильтров, и оно не уберёт из индекса уже попавшие туда адреса, потому что робот перестанет к ним заходить и не увидит noindex. Внедрять изменения такого масштаба нужно поэтапно, наблюдая за долей обхода в логах и динамикой групп в отчёте индексирования.",
