   "scenario":"Краул показал, что на 340 страницах каталога одинаковый title «Каталог товаров — Компания» и одинаковый H1 «Каталог». Страницы при этом разные: это категории и подкатегории с разным набором товаров. Часть страниц получает показы, но почти без кликов.",
   "solution":"Первый шаг — отделить проблему шаблона от проблемы дублей. Здесь страницы содержательно разные, значит вопрос в генерации: шаблон не подставляет данные, которые их различают. Решение шаблонное: формула вида «Название категории — тип раздела — Компания» с переменными, которые разработчик применит ко всем страницам сразу. Ручная правка 340 страниц — антипаттерн: она не воспроизводима и не переживёт следующий релиз, где шаблон перезапишет заголовки. То же касается H1: он должен подставляться из названия категории. Приоритизация: страницы, которые уже получают показы, дают эффект быстрее всего, поэтому с них и начинают, но само внедрение всё равно шаблонное. Проверка после выката делается в два приёма: выборочно посмотреть по одной странице каждого типа, что подстановка работает, и через две-три недели проверить CTR в отчёте эффективности по этим страницам. Отдельная оговорка: если бы часть страниц оказалась содержательно одинаковой, правка заголовков ничего бы не дала — там нужно было бы решать вопрос дублей.",
