   "scenario":"Заказчик прислал скриншот PageSpeed Insights: балл производительности 47 на мобильных. Он требует «сделать 100» и уверен, что после этого сайт выйдет в топ. В полевых данных LCP 4,1 секунды, INP 340 миллисекунд, CLS 0,28. В лабораторном отчёте отмечены крупные изображения и сторонние скрипты.",
   "solution":"Сначала разбор данных. Все три метрики вне нормы: LCP 4,1 при пороге 2,5 секунды, INP 340 при пороге 200 миллисекунд, CLS 0,28 при пороге 0,1. Важно, что это полевые данные реальных пользователей — именно на них ориентируются, а не на балл 47, который является результатом одного лабораторного прогона. Причины по метрикам: LCP чаще всего упирается в крупное несжатое изображение первого экрана и медленный ответ сервера; INP — в длинные задачи в основном потоке, обычно сторонние скрипты; CLS 0,28 при наличии сторонних скриптов почти наверняка означает элементы без заданных размеров и поздно вставляемые баннеры. Задачи разработке формулируются отдельно по каждой метрике с ожидаемым результатом, а не пересылкой отчёта целиком. С заказчиком нужен честный разговор: балл 100 не является целью, цель — попадание метрик в зелёную зону у реальных пользователей; при этом улучшение скорости не выведет страницу в топ, если она хуже отвечает на запрос, — это часть оценки, а не замена релевантности. Результат измеряется по полевым данным, а они обновляются с задержкой, поэтому первую проверку имеет смысл делать не раньше чем через месяц.",
