   "scenario":"Прошёл месяц работы. Органический трафик вырос на 22%, но заявок из органики столько же, сколько было. При этом в том же месяце компания запустила рекламную кампанию на телевидении, и брендовых запросов стало заметно больше. Заказчик ждёт отчёт и настроен услышать, что всё отлично.",
   "solution":"Ключ к этому кейсу — не поддаться соблазну показать красивую цифру. Первым делом брендовый трафик отделяется от небрендового: в отчёте эффективности это делается фильтром по запросам, содержащим название компании. Почти наверняка выяснится, что значительная часть из 22% — брендовые запросы после телерекламы, то есть не результат SEO. Дальше смотрится небрендовая динамика: если она тоже выросла, это и есть ваш результат, и его надо назвать отдельной цифрой. Отсутствие роста заявок объясняется через посадочные страницы в GA4: скорее всего, рост пришёл на информационные страницы, а не на коммерческие. Это нормальная стадия работы, и так и следует сказать: охват вырос, коммерческий результат пока нет, потому что работа шла с верхней частью воронки. Структура отчёта: что сделано, что изменилось с разделением брендового и небрендового, честное объяснение по заявкам, план на следующий месяц с фокусом на коммерческие страницы. Данные Search Console и GA4 приводятся отдельными блоками с пояснением, что они меряют разное и не должны сходиться.",
