   "scenario":"Релиз выкатили в 14:10. К 14:25 доля ошибок выросла с 0,2% до 6%, поддержка получила жалобы. Дежурный запустил откат образа на предыдущую версию. После отката ошибки не уменьшились, а выросли до 30%: старая версия приложения падает при обращении к таблице orders. В релизе была миграция, переименовавшая колонку client_id в customer_id. Резервная копия базы сделана ночью, объём таблицы — 40 млн строк.",
   "solution":"Быстрее всего вернуть сервис, накатив обратно новую версию кода: она соответствует текущей схеме. Да, это возврат к версии с 6% ошибок, но это лучше 30%, и дальше можно чинить спокойно. Альтернатива — добавить в базу совместимость, например представление или вторую колонку со старым именем, но на таблице в 40 млн строк это требует оценки блокировок и времени. Восстановление из ночной копии здесь неприемлемо: оно уничтожит все заказы за 14 часов, а исходная проблема того не стоит. Причина аварии не в самом релизе, а в том, что откат никогда не проверяли: процедура существовала только на бумаге. Правильная последовательность для такого изменения — три релиза: добавить новую колонку и писать в обе, перенести данные и переключить чтение, и только потом удалить старую. На каждом шаге и старая, и новая версия кода работоспособны, поэтому откат возможен в любой момент.",
