   "scenario":"Поддержка передаёт жалобы: у части пользователей страница оформления заказа «висит» и иногда отваливается. На панели мониторинга среднее время ответа 210 мс и почти не менялось за неделю, доля ошибок 0,3%. Продуктовая команда считает, что жалоб мало и это единичные случаи. Известно, что неделю назад выкатили новый способ расчёта скидок, обращающийся к внешнему сервису. Таймаут внешнего вызова — 10 секунд.",
   "solution":"Среднее по всему сервису — неподходящий инструмент: быстрые обращения к статике растворяют в себе медленное оформление заказа. Нужны перцентили и разделение по конечным точкам. Скорее всего p99 на оформлении заказа покажет единицы секунд, и рост совпадёт с выкатом расчёта скидок. Механизм понятен: внешний сервис иногда отвечает медленно, а таймаут в 10 секунд означает, что пользователь всё это время ждёт. Двадцать жалоб — не мера проблемы: жалуется малая доля пострадавших, остальные просто уходят. Помимо устранения причины стоит изменить две вещи. Первое — таймаут: он должен быть заметно меньше терпения пользователя, а сам расчёт скидок должен деградировать корректно, а не блокировать оформление. Второе — мониторинг: то, что проблема неделю не была видна, означает, что панель построена на среднем и не покрывает пользовательский опыт.",
