   "scenario":"Команда из шести разработчиков жалуется, что конвейер тормозит работу: сборка идёт 18 минут, из них 11 — установка зависимостей. Dockerfile начинается с копирования всего каталога проекта, затем идёт установка зависимостей и сборка. Итоговый образ весит 1,4 ГБ. Кэш в конвейере настроен, но, по словам разработчиков, «не работает». Тесты занимают 4 минуты и запускаются последовательно после сборки.",
   "solution":"Кэш работает исправно: проблема в порядке инструкций. Копирование всего каталога первым шагом означает, что любой правкой кода обесценивается слой копирования и все следующие за ним, включая установку зависимостей. Поэтому 11 минут тратятся каждый раз. Решение — сначала скопировать только файлы описания зависимостей, установить их, и лишь затем копировать остальной код. При таком порядке тяжёлый слой берётся из кэша, пока не менялся список зависимостей. Размер в 1,4 ГБ говорит о том, что в образе остались инструменты сборки: многостадийная сборка с копированием только результата уменьшит его в разы. Удаление файлов отдельной инструкцией не поможет — данные останутся в предыдущем слое. Не трогая Dockerfile, можно запускать тесты параллельно со сборкой образа, если они не зависят от него. Любое изменение стоит подтверждать замером, иначе через месяц никто не скажет, что именно помогло.",
