   "short_answer":"Чтобы робот находил страницы и обходил их регулярно, чтобы вес распределялся на важные страницы, и чтобы анкоры объясняли, о чём целевая страница. Практически это значит: у важной страницы должны быть входящие ссылки из основного контента смежных страниц, с осмысленным анкором, и она не должна быть глубоко спрятана от главной.",
