   "estimated_minutes":35,
   "example":"Служба показывает active, но приложение недоступно. journalctl -u app -n 50 даёт повторяющийся Traceback и «Read-only file system». Причина не в коде: в юните включена песочница ProtectSystem=strict, а каталог для записи не внесён в ReadWritePaths. Служба падает, systemd поднимает её заново, и статус всё это время выглядит здоровым.",
