   "short_answer":"Сначала смотрю systemctl status: что за код выхода и сколько было перезапусков. Потом journalctl по этой службе и ищу не последнюю ошибку, а первую — обычно дальше идут следствия. Дальше сверяю три вещи: что изменилось в выкате, доступны ли зависимости вроде базы, и хватает ли прав на каталоги, куда служба пишет. Если статус active, но приложение не отвечает, проверяю счётчик перезапусков: с Restart=always служба может падать по кругу и при этом выглядеть здоровой.",
