   "estimated_minutes":40,
   "example":"Приложение отвечает 502 после выката. Логи приложения пустые — значит, запрос до него не дошёл. curl с самого сервера на localhost:8080 даёт отказ в соединении: процесс не поднялся и порт никто не слушает. Прокси при этом исправен, и искать проблему надо было в приложении, а не в сети.",
   "id":"lesson-networking-diagnostics",
