   "short_answer":"Иду по цепочке запроса сверху вниз. Сначала проверяю, резолвится ли домен и в тот ли адрес. Потом — открывается ли TCP-соединение на нужный порт: отказ и таймаут означают разные вещи. Дальше curl -v, чтобы увидеть TLS и код ответа. Код подсказывает, где смотреть: 502 и 504 уводят к приложению за прокси, 503 — к самому сервису, а 4xx означает, что сервис жив и отвечает осмысленно. Параллельно уточняю, у всех ли недоступно или у части пользователей: это сразу отделяет общую аварию от проблемы одного региона или провайдера.",
