   "short_answer":"Считаю его скомпрометированным с этой минуты — независимо от того, как быстро я его удалю. Первым делом отзываю токен и выпускаю новый: пока старый действует, всё остальное неважно. Потом смотрю по логам, использовали ли его, и оцениваю ущерб. Дальше — чистка истории репозитория, но это уже уборка, а не защита: клоны могли уйти куда угодно. И в конце разбираюсь, как он туда попал, и закрываю саму возможность: проверка секретов до коммита и хранилище секретов вместо файла рядом с кодом.",
