   "estimated_minutes":40,
   "example":"Сервис держит 99,95% при цели 99,9%. Бюджет ошибок израсходован на треть, и команда спокойно катит изменения. После неудачного релиза бюджет выработан полностью — по договорённости выкаты новых функций приостанавливаются, пока команда не вернёт показатель.",
