   "estimated_minutes":35,
   "example":"Выкат в 14:10, первые ошибки в 14:12, тревога сработала в 14:40, откат в 14:47. Главная находка постмортема не в причине сбоя, а в этих 28 минутах между поломкой и тревогой: мониторинг не покрывал именно этот сценарий.",
