   "model_answer_full":"Это вопрос-маркер: по нему сразу видно, понимает ли кандидат разницу между этапами. Разверните ответ до практики: для файлов без HTML-разметки, например PDF, мета-тег поставить негде, поэтому используется HTTP-заголовок X-Robots-Tag. Если нужно убрать страницу срочно, можно дополнительно воспользоваться инструментом удаления в Search Console, но это временная мера, а не замена noindex. Хорошим дополнением будет упоминание, что robots.txt — публичный файл, и закрывать им приватные разделы бессмысленно.",
