   "model_answer_full":"Отличие подготовленного кандидата — знание, что canonical не является командой. Приведите практический маркер: в проверке URL есть два поля — канонический адрес, указанный пользователем, и выбранный Google. Их расхождение означает, что Google счёл страницы дублями по своим признакам, и надо разбираться с содержимым и внутренними ссылками, а не переотправлять страницу. Отдельно стоит упомянуть частую ошибку с пагинацией: canonical со второй страницы на первую прячет от поисковика часть каталога.",
