   "model_answer_full":"Три обязательных правила: взаимность, самоссылка и валидные коды. Самая частая ошибка в кодах — писать регион вместо языка или несуществующие сочетания вроде en-UK вместо en-GB. Вторая распространённая ошибка концептуальная: ставить canonical с языковых версий на основную, ожидая, что версии будут ранжироваться — они не будут, потому что canonical говорит поисковику считать их дублями. Третья — редирект по геолокации: пользователю он может быть удобен, но робот, приходящий из одной страны, не увидит остальные версии, поэтому лучше предлагать переключение, а не навязывать его.",
