   "model_answer_full":"Этот вопрос часто задают как проверку на мифы. Сильный ответ включает честное ограничение: для большинства небольших сайтов краулинговый бюджет не является причиной проблем, и объяснять им отсутствие индексации у сайта на пятьдесят страниц — ошибка. Добавьте, как это измеряется на практике: анализом логов сервера, который показывает, какие URL робот запрашивал, как часто и с какими кодами. Типичная находка — большая доля обхода уходит на параметрические страницы фильтров. И уточните, что бюджет влияет на скорость появления страниц в индексе, а не на их позиции.",
   "model_answer_short":"Это объём обхода, который поисковик готов потратить на сайт: сочетание допустимой нагрузки на сервер и интереса к сайту. Реальной проблемой становится на крупных сайтах с десятками тысяч URL. Тратят его дубли по параметрам, цепочки редиректов, мягкие 404 и медленный сервер. Экономят чисткой мусорных URL, ускорением ответа и внутренней перелинковкой. На сайте в сотню страниц это обычно не узкое место.",
