   "intent":"Проверка практики работы с краулером",
   "model_answer_full":"Практический ответ строится вокруг того, что делают с результатом, а не какие вкладки открывают. Тысяча предупреждений обычно сводится к трём-четырём типам проблем, и задача — увидеть эти типы. Полезно назвать настройки, которые меняют картину: соблюдение robots.txt, user-agent, режим рендеринга. И назвать приём приоритизации: соединить выгрузку с данными Search Console по URL и в первую очередь чинить проблемы на страницах, которые дают трафик, — это отличает специалиста от того, кто просто запустил программу.",
   "model_answer_short":"Сначала коды ответа: 4xx и 5xx и откуда на них ведут ссылки. Затем цепочки редиректов. Потом дубли и пустые title, description и H1. Отдельно смотрю canonical: ссылается ли страница на себя. Для сайтов на JavaScript включаю режим рендеринга, иначе увижу пустые страницы. Дальше выгружаю в таблицу и приоритизирую: важно не число предупреждений, а сколько страниц и какого типа затронуто.",
