   "model_answer_full":"Оценивается доведение до результата. Много кандидатов останавливаются на выгрузке. Полный цикл: источники, сведение, чистка, интент, кластеризация, mapping. Отдельно проговорите критерий кластеризации — пересечение выдачи, а не совпадение слов, потому что смысловая группировка ошибается на смежных темах. И правило одного кластера на страницу: если под группу нет подходящей страницы, значит в плане появляется новая. Полезно добавить оценку достижимости: запрос с высокой частотностью, у которого весь топ занят агрегаторами, стоит поставить ниже по приоритету.",
