   "model_answer_full":"Это вопрос на устойчивость. Правильная реакция — согласиться с фактом без защиты и сразу перейти к тому, что у вас есть. Три опоры: самостоятельная практика с конкретными примерами, переносимые навыки из прежней области, и готовность закрывать рутинные задачи с первого дня. Последнее важно: junior нанимают, чтобы он снял с команды объём работы, поэтому назовите конкретно, что вы можете делать уже сейчас без обучения. Обещания «я быстро учусь» работают только с доказательством — приведите пример того, что освоили самостоятельно и за какой срок.",
