   "model_answer_full":"Здесь проверяют язык. Ни одного термина, который заказчику пришлось бы гуглить: не «краулинг», а «поисковик должен заново зайти на страницы». Структура объяснения: механизм, промежуточные признаки, честная граница. Промежуточные метрики важны — они дают заказчику ощущение движения до появления денег: рост показов, появление новых запросов, улучшение статусов индексации. И обязательно проговорите, что вы не обещаете: конкретные позиции и точные даты. Заказчики обычно нормально принимают отказ от обещаний, если вместо него получают понятный механизм и промежуточные ориентиры.",
   "model_answer_short":"Объясняю механизм простыми словами: сначала поисковик должен заново обойти изменённые страницы, потом переоценить их, и только потом это отразится на показах. Это занимает недели. При этом промежуточный результат виден раньше: рост показов и появление новых запросов в Search Console. Конкретные сроки и позиции не обещаю — это решение поисковой системы, а не наше.",
