   "model_answer_full":"Проверяется не умение настоять, а умение работать вместе. Первый ход всегда один — выяснить аргументы, потому что разработчик часто видит ограничение системы, о котором вы не знаете. Второй — честно проверить себя: если вы ошиблись, признать это дешевле, чем защищать позицию. Третий — если задача действительно нужна, переформулировать её через последствия для бизнеса, а не через SEO-термины, и обсуждать варианты реализации, а не единственный. Эскалация к руководителю уместна только когда исчерпаны аргументы и вопрос действительно важен, и подаётся как просьба расставить приоритеты, а не как жалоба. Договорённость фиксируется письменно — это снимает споры о том, что решили.",
   "model_answer_short":"Сначала выясняю, в чём именно он видит проблему: возможно, он прав или знает ограничение, которого я не вижу. Если аргумент технический, проверяю свою позицию по документации. Если задача всё же нужна, объясняю последствия через результат: что произойдёт с трафиком, если не сделать. Дальше ищем вариант, который решает задачу и укладывается в их ограничения. Итог фиксирую письменно.",
