   "intent":"Проверка понимания цепочки запроса",
   "model_answer_full":"Ценность ответа не в перечислении этапов, а в том, что кандидат связывает каждый с конкретным симптомом. Сильный ответ сразу говорит, чем проверяется каждый шаг, — это показывает, что человек действительно разбирал недоступность, а не пересказывает схему из учебника.",
   "model_answer_short":"Сначала имя разрешается в адрес, и здесь работает кэш с учётом TTL. Потом устанавливается TCP-соединение на нужный порт. Дальше TLS-рукопожатие с проверкой сертификата. И только после этого уходит HTTP-запрос, который может пройти через балансировщик и прокси, прежде чем попадёт в приложение. Для эксплуатации важно, что каждый этап ломается по-своему: отказ соединения — это одно, истёкший сертификат — другое, а 502 от прокси — третье.",
