   "model_answer_short":"Возникнет дрейф: описание и реальность разошлись. Ближайший plan покажет намерение вернуть ресурс к тому, что записано в коде, и если применить не глядя, изменение коллеги пропадёт. Правильно — решить осознанно: если изменение нужное, вношу его в код; если случайное, даю применить и вернуть прежнее состояние. Отдельно проговариваю с командой, что менять ресурсы мимо кода нельзя, иначе через месяц никто не знает, что откуда взялось.",
