   "model_answer_full":"Оценивается способность перевести спор о позициях в разговор об интересах. Ответ, где кандидат просто оказался прав, показывает негибкость. Хорошо работает признание, что часть требований оппонента была обоснованной: это показывает, что человек слышит, а не только настаивает.",
   "model_answer_short":"Разработчики хотели выкатывать напрямую в продакшен, потому что промежуточная среда замедляла работу. Я был против, но вместо спора выяснил, что им мешало: выкат в тестовую среду занимал сорок минут. Мы договорились: я ускоряю тестовый выкат, они через него проходят. В итоге и скорость выросла, и проверка сохранилась. Мне здесь важно было понять их интерес, а не отстоять своё правило.",
