   "model_answer_full":"Отрицание ошибок — самый слабый вариант ответа: он читается либо как отсутствие опыта, либо как нежелание признавать. Сильный ответ содержит реальные последствия и заканчивается изменением в собственной работе. Важно, чтобы изменение было конкретным правилом, а не обещанием быть внимательнее.",
